{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "reconditioning_starter_l4l5",
    "name": "2-Week Reconditioning Starter (L4-L5 Precaution)",
    "description": "Two-week introductory general strength program for a 42-year-old male post L4-L5 herniation. Avoids heavy spinal loading and loaded spinal flexion; focuses on safe reconditioning, core stability, hip/glute strength, and unloaded or machine-based progressions.",
    "type": "workout",
    "visibility": "private",
    "metadata": {
      "created_at": "2026-06-05T00:00:00Z",
      "updated_at": "2026-06-05T00:00:00Z",
      "created_by": "trainer",
      "difficulty": "beginner",
      "estimated_duration_days": 14,
      "language": "en",
      "tags": [
        "rehab",
        "low_back",
        "starter",
        "strength"
      ]
    },
    "goals": [
      {
        "id": "safe_reconditioning",
        "type": "primary",
        "category": "strength",
        "name": "Safe reconditioning",
        "description": "Rebuild general strength, improve core control and hip/glute capacity while avoiding heavy spinal compression and loaded spinal flexion.",
        "target": {
          "metric": "session_adherence",
          "target_value": 12,
          "unit": "sessions",
          "measurement_type": "absolute"
        },
        "milestones": [
          {
            "id": "complete_first_week",
            "name": "Complete week 1",
            "reward_points": 10
          },
          {
            "id": "complete_second_week",
            "name": "Complete week 2",
            "reward_points": 15
          }
        ]
      }
    ],
    "requirements": {
      "min_age": 18,
      "fitness_level": [
        "beginner",
        "return_to_train"
      ],
      "equipment": [
        {
          "id": "body_and_machines",
          "name": "Gym — machines, dumbbells, cable, machines for leg press/row",
          "required": true,
          "alternatives": [
            "resistance_bands",
            "kept_loads_light"
          ]
        }
      ],
      "contraindications": [
        {
          "condition": "lower_back_injury",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": [
            "barbell_back_squat",
            "barbell_deadlift",
            "romanian_deadlift",
            "kettlebell_swing",
            "loaded_spinal_flexion"
          ]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 4,
        "min_minutes_per_day": 20,
        "max_minutes_per_day": 60
      }
    },
    "personalization": {
      "inputs": [
        {
          "id": "user.age",
          "type": "number",
          "source": "user.age",
          "label": "Age"
        },
        {
          "id": "user.clearance_obtained",
          "type": "boolean",
          "source": "user.clearance_obtained",
          "label": "Medical clearance obtained"
        },
        {
          "id": "user.experience_level",
          "type": "enum",
          "source": "user.experience_level",
          "label": "Experience level",
          "options": [
            "beginner",
            "intermediate",
            "advanced"
          ]
        }
      ],
      "rules": [
        {
          "id": "require_clearance_if_not_flagged",
          "condition": {
            "field": "user.clearance_obtained",
            "op": "eq",
            "value": false
          },
          "actions": [
            {
              "type": "require_clearance",
              "scope": "plan"
            }
          ]
        }
      ]
    },
